<style>
	.scene-istanbul {
		--sky1: #8fd0ef;
		--sky2: #fbeed4;
		--sun: #fff0b8;
		--cloud: #fff;
		--water1: #6fb0c6;
		--water2: #3f8aa6;
		--far: #b6c3c2;
		--far2: #8fa3a8;
		--rose: #e4b08a;
		--rose2: #d4916e;
		--butt: #c58a68;
		--lead: #8e9fb3;
		--lead2: #a6b3c2;
		--wh: #f3ead8;
		--wh2: #d8cdb6;
		--brk: #c07a5a;
		--cone: #8b99ab;
		--glass: #4a5368;
		--dark: #3a3040;
		--gold: #e8b030;
		--bstone: #e3e6ea;
		--bstone2: #c3c9d2;
		--blue: #6f93bd;
		--blue2: #8aa7c8;
		--stone2: #bda98a;
		--stripe: #d9503f;
		--hullk: #2b3a52;
		--hull2: #6a3a2e;
		--sail2: #e08a3a;
	}
	:global(.dark) .scene-istanbul {
		--sky1: #0b1530;
		--sky2: #262d56;
		--sun: #e8eef8;
		--cloud: #2a3558;
		--water1: #12294a;
		--water2: #08142a;
		--far: #1a2646;
		--far2: #2c3a5c;
		--rose: #8a6458;
		--rose2: #785450;
		--butt: #6c4a48;
		--lead: #4f6280;
		--lead2: #5a6a85;
		--wh: #9a9aa8;
		--wh2: #76778a;
		--brk: #7a4a44;
		--cone: #4a5a74;
		--glass: #f1bf62;
		--dark: #0a0f1d;
		--gold: #f0c35a;
		--bstone: #7d8aa4;
		--bstone2: #5d6a86;
		--blue: #3f5f8c;
		--blue2: #4a6a96;
		--stone2: #4a5068;
		--stripe: #a8403a;
		--hullk: #0a1224;
		--hull2: #3d2430;
		--sail2: #a8642e;
	}
	.scene {
		position: absolute;
		inset: 0;
		overflow: hidden;
		background: linear-gradient(180deg, var(--sky1), var(--sky2) 70%, var(--water1) 71%, var(--water1) 78%, var(--water2));
	}
	svg {
		position: absolute;
		inset: 0;
		width: 100%;
		height: 100%;
		-webkit-mask-image: linear-gradient(90deg, transparent, #000 9%, #000 70%, transparent 97%);
		mask-image: linear-gradient(90deg, transparent, #000 9%, #000 70%, transparent 97%);
	}
</style>
